import{_ as t,o as a,c as i,aj as s}from"./chunks/framework.C6uXqnaX.js";const p=JSON.parse('{"title":"Agent Skills","description":"","frontmatter":{},"headers":[],"relativePath":"en/ai/agent-skills.md","filePath":"en/ai/agent-skills.md"}'),l={name:"en/ai/agent-skills.md"};function n(r,e,o,d,c,g){return a(),i("div",null,e[0]||(e[0]=[s('<h1 id="agent-skills" tabindex="-1">Agent Skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent Skills&quot;">​</a></h1><p>Agent Skills are specialized, domain-specific instructions and capabilities designed for AI agents like Gemini CLI. These skills provide architectural guidance, generate idiomatic Angular code, and help scaffold new projects using modern best practices.</p><p>By using Agent Skills, you can ensure that the AI agent you are working with has the most up-to-date information about Angular&#39;s conventions, reactivity models (like Signals), and project structure.</p><h2 id="available-skills" tabindex="-1">Available Skills <a class="header-anchor" href="#available-skills" aria-label="Permalink to &quot;Available Skills&quot;">​</a></h2><p>The Angular team maintains a collection of official skills that are regularly updated to stay in sync with the latest framework improvements.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Skill</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>angular-developer</code></strong></td><td style="text-align:left;">Generates Angular code and provides architectural guidance. Useful for creating components, services, or obtaining best practices on reactivity (signals, linkedSignal, resource), forms, dependency injection, routing, SSR, accessibility (ARIA), animations, styling, testing, or CLI tooling.</td></tr><tr><td style="text-align:left;"><strong><code>angular-new-app</code></strong></td><td style="text-align:left;">Creates a new Angular app using the Angular CLI. Provides important guidelines for effectively setting up and structuring a modern Angular application.</td></tr></tbody></table><h2 id="using-agent-skills" tabindex="-1">Using Agent Skills <a class="header-anchor" href="#using-agent-skills" aria-label="Permalink to &quot;Using Agent Skills&quot;">​</a></h2><p>Agent Skills are designed to be used with agentic coding tools like <a href="https://geminicli.com/docs/cli/skills/" target="_blank" rel="noreferrer">Gemini CLI</a>, <a href="https://antigravity.google/docs/skills" target="_blank" rel="noreferrer">Antigravity</a> and more. Activating a skill loads the specific instructions and resources needed for that task.</p><p>To use these skills in your own environment you may follow the instructions for your specific tool or use a community tool like <a href="https://skills.sh/" target="_blank" rel="noreferrer">skills.sh</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/angular/skills</span></span></code></pre></div>',10)]))}const u=t(l,[["render",n]]);export{p as __pageData,u as default};
